// Basic function
def add(a: Int, b: Int): Int = a + b

// Default parameters and named arguments
def greet(name: String, greeting: String = "Hello"): String =
  s"$greeting, $name!"
greet(greeting = "Hi", name = "Alice")

// Varargs
def sum(nums: Int*): Int = nums.sum
sum(1, 2, 3, 4, 5)

// Higher-order functions
def apply(f: Int => Int, x: Int): Int = f(x)
apply(x => x * x, 5)   // 25

def twice(f: Int => Int): Int => Int = x => f(f(x))
twice(_ + 1)(5)   // 7

// Anonymous functions
val square: Int => Int = x => x * x
val isEven = (n: Int) => n % 2 == 0

// Currying / partial application
def multiply(x: Int)(y: Int): Int = x * y
val triple = multiply(3)   // partially applied
triple(5)   // 15

// Function composition
val double = (x: Int) => x * 2
val inc    = (x: Int) => x + 1
val doubleInc = double andThen inc   // inc after double
doubleInc(5)   // 11

// Tail recursion (safe — no stack overflow)
import scala.annotation.tailrec
@tailrec
def factorial(n: Long, acc: Long = 1): Long =
  if n <= 1 then acc
  else factorial(n - 1, n * acc)

// Option monadic operations
def divide(a: Int, b: Int): Option[Double] =
  if b == 0 then None else Some(a.toDouble / b)

val result = for
  x <- divide(10, 2)
  y <- divide(x.toInt, 2)
yield y + 1  // Some(3.5)
