import scala.concurrent.{Future, Await}
import scala.concurrent.ExecutionContext.Implicits.global
import scala.concurrent.duration._

// Future — asynchronous computation
val f1 = Future { Thread.sleep(100); 42 }
val f2 = Future { Thread.sleep(50); "hello" }

// Map and flatMap
val doubled = f1.map(_ * 2)             // Future[Int]
val chained = f1.flatMap(n => Future { n.toString })

// for comprehension with futures (parallel!)
val combined = for
  n <- f1
  s <- f2
yield s"$s: $n"
combined.foreach(println)

// Future.sequence — wait for all
val futures = List(Future(1), Future(2), Future(3))
val all: Future[List[Int]] = Future.sequence(futures)

// Error recovery
val safe = Future { 10 / 0 }
  .recover { case e: ArithmeticException => -1 }

// Await (blocking — use only at the top level!)
val value = Await.result(f1, 5.seconds)
println(value)   // 42

// Promise — write-once container
import scala.concurrent.Promise
val p = Promise[Int]()
Future { Thread.sleep(100); p.success(42) }
p.future.foreach(println)

// Handle failure
futures.head.failed.foreach(e => println(s"Error: $e"))
